```yaml
- ansible.builtin.apt: {name: apache2, state: present}
- ansible.builtin.apt: {name: foo, update_cache: yes}
- ansible.builtin.apt: {name: foo, state: absent}
- ansible.builtin.apt:
    pkg: [foo, foo-tools]
- ansible.builtin.apt: {name: foo=1.00}
- ansible.builtin.apt:
    name: nginx
    state: latest
    default_release: squeeze-backports
    update_cache: yes
- ansible.builtin.apt: {name: nginx=1.18.0, allow_downgrade: yes}
- ansible.builtin.apt: {name: "*", state: latest}   # upgrade all
- ansible.builtin.apt: {upgrade: dist}
- ansible.builtin.apt: {update_cache: yes}
```
